styles.css:
background-image:
	linear-gradient(to right, rgba(255, 253, 244, 0.035) 1px, transparent 1px),
	linear-gradient(to bottom, rgba(255, 253, 244, 0.035) 1px, transparent 1px);
background-size: 48px 48px;

	/* The Resume nav item stays amber whether or not it is the current page,
	   because it opens the resume viewer rather than navigating. It needs a class
	   rather than a colour attribute: core/navigation-link declares no color
	   support and never reads textColor from its own attributes, so a textColor
	   attribute parses and is then discarded without a warning. The class is
	   emitted by patterns/header.php. */
	.site-header__nav-resume,
	.site-header__nav-resume:visited {
		color: var(--wp--preset--color--accent);
	}

	.site-header__nav-resume:hover {
		color: var(--wp--preset--color--accent-hover);
	}
